    except:
        dt = 1.0
    if not math.isfinite(y_m):
        y_m = 0.5
    if not math.isfinite(tgt):
        tgt = 0.5
    if not math.isfinite(dt) or dt <= 0.0:
        dt = 1.0
    if dt < 0.1:
        dt = 0.1
    if dt > 10.0:
        dt = 10.0
    if y_m < 0.0:
        y_m = 0.0
    if y_m > 1.0:
