    try:
        integ_prev = float(integ_prev)
    except:
        integ_prev = 0.0
    if not math.isfinite(yf_prev):
        yf_prev = y_m
    if not math.isfinite(integ_prev):
        integ_prev = 0.0
    yf_prev = _clamp(yf_prev, 0.0, 1.0)
    integ_prev = _clamp(integ_prev, -0.35, 0.35)
