    e = tgt - yf
    if not math.isfinite(e):
        e = 0.0
    integ = integ_prev
    if abs(e) < E_FREEZE:
        integ = integ_prev + Ki * e * dt
        integ = _clamp(integ, -INT_LIM, INT_LIM)
    u_raw = ff + Kp * e + integ
    if not math.isfinite(u_raw):
        u_raw = ff
        integ = integ_prev
